import {uid,clone,I} from './core.js';
export function traceMask(mask,w,h,{noise=1}={}){
 if(!Number.isFinite(noise)||noise<1)throw Error('Ruido mínimo inválido.');if(!Number.isInteger(w)||!Number.isInteger(h)||w<=0||h<=0||w*h>1048576||mask.length!==w*h)throw Error('La vectorización admite hasta 1 megapíxel.');
 const labels=new Int32Array(w*h).fill(-1),components=[];for(let i=0;i<mask.length;i++){if(!mask[i]||labels[i]>=0)continue;const id=components.length,queue=[i];labels[i]=id;for(let k=0;k<queue.length;k++){const p=queue[k],x=p%w,y=Math.floor(p/w);for(const q of [x>0?p-1:-1,x+1<w?p+1:-1,y>0?p-w:-1,y+1<h?p+w:-1])if(q>=0&&mask[q]&&labels[q]<0){labels[q]=id;queue.push(q);}}components.push(queue);}
 let anchorBudget=0;const result=[];for(let id=0;id<components.length;id++){if(components[id].length<noise)continue;const edges=new Map(),inside=(x,y)=>x>=0&&y>=0&&x<w&&y<h&&labels[y*w+x]===id,add=(x,y,d)=>{const key=x+','+y;const list=edges.get(key)||[];list.push(d);edges.set(key,list);},steps=[[1,0],[0,1],[-1,0],[0,-1]];for(const i of components[id]){const x=i%w,y=Math.floor(i/w);if(!inside(x,y-1))add(x,y,0);if(!inside(x+1,y))add(x+1,y,1);if(!inside(x,y+1))add(x+1,y+1,2);if(!inside(x-1,y))add(x,y+1,3);}const loops=[];while(edges.size){const [key,ds]=edges.entries().next().value,[sx,sy]=key.split(',').map(Number);let x=sx,y=sy,d=ds[0],points=[],count=0;do{const k=x+','+y,list=edges.get(k);if(!list?.includes(d))throw Error('Contorno de imagen inválido.');list.splice(list.indexOf(d),1);if(!list.length)edges.delete(k);points.push({x,y});x+=steps[d][0];y+=steps[d][1];if(x===sx&&y===sy)break;const next=edges.get(x+','+y);if(!next?.length)throw Error('Contorno de imagen abierto.');d=[(d+1)%4,d,(d+3)%4,(d+2)%4].find(q=>next.includes(q));if(++count>w*h*4)throw Error('Contorno demasiado complejo.');}while(true);points=points.filter((p,i,ps)=>{const a=ps[(i+ps.length-1)%ps.length],b=ps[(i+1)%ps.length];return (p.x-a.x)*(b.y-p.y)!==(p.y-a.y)*(b.x-p.x);});const area=points.reduce((a,p,i)=>{const q=points[(i+1)%points.length];return a+p.x*q.y-q.x*p.y;},0);anchorBudget+=points.length;if(anchorBudget>100000)throw Error('La imagen genera más de 100000 nodos. Reducí el tamaño o aumentá el filtro de ruido.');loops.push({points,area});}const outer=loops.filter(l=>l.area>0),holes=loops.filter(l=>l.area<0);for(const loop of outer){if(result.length>=5000)throw Error('La imagen genera demasiados contornos. Aumentá el filtro de ruido.');result.push({nodes:loop.points.map(p=>({...p,nid:uid()})),closed:true,subpaths:holes.map(l=>({nodes:l.points.map(p=>({...p,nid:uid()})),closed:true}))});}}return result;
}
export function traceRaster(rgba,w,h,{threshold=128,noise=4,alpha=128}={}){if(!Number.isInteger(w)||!Number.isInteger(h)||w<=0||h<=0||w*h>1048576)throw Error('La vectorización admite hasta 1 megapíxel.');if(rgba.length!==w*h*4||!Number.isFinite(threshold)||threshold<0||threshold>255||!Number.isFinite(alpha)||alpha<0||alpha>255)throw Error('Imagen o umbral inválido.');const mask=new Uint8Array(w*h);for(let i=0;i<mask.length;i++){const j=i*4;mask[i]=rgba[j+3]>=alpha&&rgba[j+3]>0&&.2126*rgba[j]+.7152*rgba[j+1]+.0722*rgba[j+2]<threshold;}return traceMask(mask,w,h,{noise});}
export function traceImageObjects(image,rgba,w,h,options={}){const contours=traceRaster(rgba,w,h,options);const m=image.matrix||I();return contours.map((p,i)=>({id:uid(),type:'path',name:image.name+' · vector '+(i+1),...p,matrix:[m[0]*image.w/w,m[1]*image.w/w,m[2]*image.h/h,m[3]*image.h/h,m[4],m[5]],fill:'#252a29',stroke:'none',width:0,opacity:image.opacity??1,category:'graphic',semanticType:'tracedGraphic',traceSource:image.id,mirrorPolicy:'none',symmetryExcluded:true,...(image.clip?{clip:image.clip}:{})}));}
